-- Conteo físico Xtensor: ejecutar completo en Supabase SQL Editor.
-- Cambie los PIN iniciales en el INSERT de access_roles antes de ejecutar en producción.
create extension if not exists pgcrypto with schema extensions;

create table if not exists public.access_roles (
  role_code text primary key,
  display_name text not null,
  pin_hash text not null,
  is_admin boolean not null default false,
  enabled boolean not null default true
);
alter table public.access_roles add column if not exists enabled boolean not null default true;
insert into public.access_roles(role_code,display_name,pin_hash,is_admin) values
('admin','Administrador',extensions.crypt('planta2026',extensions.gen_salt('bf')),true),
('operario','Operario',extensions.crypt('operario',extensions.gen_salt('bf')),false)
on conflict(role_code) do nothing;
update public.access_roles set pin_hash=extensions.crypt('planta2026',extensions.gen_salt('bf')) where role_code='admin';
update public.access_roles set display_name='Operario',enabled=true where role_code='operario';
update public.access_roles set enabled=false where role_code like 'operario_%';

create table if not exists public.inventory_items (
 id uuid primary key default gen_random_uuid(), product_code text unique not null, product_name text not null,
 unit text, warehouse_code text not null default '01', system_quantity numeric, unit_value numeric, total_value numeric, category text
);
create table if not exists public.count_tasks (
 id uuid primary key default gen_random_uuid(), inventory_item_id uuid unique not null references public.inventory_items(id) on delete cascade,
 product_code text not null, product_name text not null, unit text, assigned_role text references public.access_roles(role_code),
 counted_quantity numeric, observation text, counted_at date, updated_at timestamptz not null default now()
);
create table if not exists public.inventory_sessions (
 token uuid primary key default gen_random_uuid(), role_code text not null references public.access_roles(role_code), responsible_name text, expires_at timestamptz not null default now()+interval '18 hours', created_at timestamptz not null default now()
);
alter table public.inventory_sessions add column if not exists responsible_name text;
create table if not exists public.count_activity (
 id bigint generated always as identity primary key, task_id uuid not null references public.count_tasks(id) on delete cascade,
 actor_role text not null references public.access_roles(role_code), responsible_name text, counted_quantity numeric, observation text, recorded_at timestamptz not null default now()
);
alter table public.count_activity add column if not exists responsible_name text;
update public.count_tasks set assigned_role='operario' where assigned_role is distinct from 'operario';
create index if not exists count_tasks_role_state_idx on public.count_tasks(assigned_role, counted_quantity);
create index if not exists count_tasks_code_idx on public.count_tasks(product_code);
create index if not exists inventory_sessions_expiry_idx on public.inventory_sessions(expires_at);
create index if not exists count_activity_task_time_idx on public.count_activity(task_id, recorded_at desc);
alter table public.access_roles enable row level security;
alter table public.inventory_items enable row level security;
alter table public.count_tasks enable row level security;
alter table public.inventory_sessions enable row level security;
alter table public.count_activity enable row level security;

create or replace function public.session_role(p_token uuid) returns text language sql stable security definer set search_path=public as $$
 select role_code from public.inventory_sessions where token=p_token and expires_at>now();
$$;
create or replace function public.session_admin(p_token uuid) returns boolean language sql stable security definer set search_path=public as $$
 select coalesce((select is_admin from public.access_roles where role_code=public.session_role(p_token)),false);
$$;
drop function if exists public.inventory_login(text,text);
drop function if exists public.inventory_login(text,text,text);
create function public.inventory_login(p_role text,p_pin text,p_responsible text default null) returns table(token uuid,role_code text,display_name text,is_admin boolean,responsible_name text) language plpgsql security definer set search_path=public as $$
declare r public.access_roles%rowtype; t uuid;
begin
 select * into r from public.access_roles as ar where ar.role_code=p_role;
 if not found or not r.enabled or (r.is_admin and extensions.crypt(p_pin,r.pin_hash)<>r.pin_hash) then raise exception 'Perfil o PIN incorrecto'; end if;
 if not r.is_admin and coalesce(trim(p_responsible),'') not in ('Daniel García','Germán Villada','Daniel Duque','Juan Felipe','Cristian Rodríguez') then raise exception 'Seleccione la persona responsable del registro'; end if;
 delete from public.inventory_sessions where expires_at<now();
 insert into public.inventory_sessions(role_code,responsible_name) values(r.role_code,nullif(trim(p_responsible),'')) returning inventory_sessions.token into t;
 return query select t,r.role_code,r.display_name,r.is_admin,nullif(trim(p_responsible),'');
end; $$;
drop function if exists public.inventory_tasks(uuid,text,text);
drop function if exists public.inventory_find_tasks(uuid,text,text);
create function public.inventory_tasks(p_token uuid,p_state text default 'pending',p_search text default '') returns table(id uuid,product_code text,product_name text,unit text,counted_quantity numeric,observation text,counted_at date,assigned_role text,category text) language plpgsql security definer set search_path=public as $$
declare role text:=public.session_role(p_token); admin boolean:=public.session_admin(p_token);
begin
 if role is null then raise exception 'Sesión vencida'; end if;
 return query select t.id,t.product_code,t.product_name,t.unit,t.counted_quantity,t.observation,t.counted_at,t.assigned_role,i.category from public.count_tasks t join public.inventory_items i on i.id=t.inventory_item_id
 where (admin or t.assigned_role=role) and (case when p_state='counted' then t.counted_quantity is not null else t.counted_quantity is null end)
 and (p_search='' or lower(t.product_code||' '||t.product_name) like '%'||lower(p_search)||'%') order by t.product_code;
end; $$;
create or replace function public.inventory_summary(p_token uuid) returns table(pending_count bigint,counted_count bigint) language plpgsql security definer set search_path=public as $$
declare role text:=public.session_role(p_token); admin boolean:=public.session_admin(p_token);
begin
 if role is null then raise exception 'Sesión vencida'; end if;
 return query select count(*) filter(where t.counted_quantity is null),count(*) filter(where t.counted_quantity is not null) from public.count_tasks t where admin or t.assigned_role=role;
end; $$;
create or replace function public.inventory_save_count(p_token uuid,p_task uuid,p_quantity numeric,p_observation text) returns void language plpgsql security definer set search_path=public as $$
declare role text:=public.session_role(p_token); responsible text;
begin
 if role is null then raise exception 'Sesión vencida'; end if;
 select responsible_name into responsible from public.inventory_sessions where token=p_token;
 update public.count_tasks set counted_quantity=p_quantity, observation=nullif(trim(p_observation),''), counted_at=case when p_quantity is null then null else (now() at time zone 'America/Bogota')::date end, updated_at=now()
 where id=p_task;
 if not found then raise exception 'Ítem no encontrado'; end if;
 insert into public.count_activity(task_id,actor_role,responsible_name,counted_quantity,observation) values(p_task,role,responsible,p_quantity,nullif(trim(p_observation),''));
end; $$;
drop function if exists public.inventory_admin_tasks(uuid);
create function public.inventory_admin_tasks(p_token uuid) returns table(id uuid,product_code text,product_name text,unit text,category text,system_quantity numeric,unit_value numeric,warehouse_code text,assigned_role text,counted_quantity numeric,observation text,counted_at date,last_actor text,last_recorded_at timestamptz) language plpgsql security definer set search_path=public as $$
begin if not public.session_admin(p_token) then raise exception 'Solo administrador'; end if;
 return query select t.id,i.product_code,i.product_name,i.unit,i.category,i.system_quantity,i.unit_value,i.warehouse_code,t.assigned_role,t.counted_quantity,t.observation,t.counted_at,a.display_name,a.recorded_at from public.count_tasks t join public.inventory_items i on i.id=t.inventory_item_id left join lateral (select coalesce(ca.responsible_name,ar.display_name) as display_name,ca.recorded_at from public.count_activity ca join public.access_roles ar on ar.role_code=ca.actor_role where ca.task_id=t.id order by ca.recorded_at desc limit 1) a on true order by i.product_code; end; $$;
create or replace function public.inventory_activity(p_token uuid,p_limit integer default 500) returns table(product_code text,product_name text,display_name text,counted_quantity numeric,observation text,recorded_at timestamptz) language plpgsql security definer set search_path=public as $$
begin if not public.session_admin(p_token) then raise exception 'Solo administrador'; end if;
 return query select t.product_code,t.product_name,coalesce(ca.responsible_name,ar.display_name),ca.counted_quantity,ca.observation,ca.recorded_at from public.count_activity ca join public.count_tasks t on t.id=ca.task_id join public.access_roles ar on ar.role_code=ca.actor_role order by ca.recorded_at desc limit greatest(1,least(coalesce(p_limit,500),2000)); end; $$;
create or replace function public.inventory_assign(p_token uuid,p_task uuid,p_role text) returns void language plpgsql security definer set search_path=public as $$
begin if not public.session_admin(p_token) then raise exception 'Solo administrador'; end if; update public.count_tasks set assigned_role=nullif(p_role,''),updated_at=now() where id=p_task; end; $$;
grant execute on function public.inventory_login(text,text,text),public.inventory_tasks(uuid,text,text),public.inventory_summary(uuid),public.inventory_save_count(uuid,uuid,numeric,text),public.inventory_admin_tasks(uuid),public.inventory_activity(uuid,integer),public.inventory_assign(uuid,uuid,text) to anon,authenticated;

